  async function persistB2B(closeAfter=false){const p=prepareB2B();if(!p)return false;try{const saved=await B.upsertProduct(p);state.products=S.getProducts();if(closeAfter)state.b2bEditor=null;else{const fresh=state.products.find(x=>String(x.id)===String(saved.id));state.b2bEditor={...blankB2B(),...structured(fresh||p),images:[...((fresh||p).images||[])],variants:[],subItemIds:[]};state.editSections={};}render();notify(closeAfter?'B2B item created.':'B2B section saved.');return true;}catch(err){notify(err.message||'Could not save B2B item');return false;}}
